    private static string? imagePath;

    public static string GetImagePath()
    {
        if (imagePath != null && File.Exists(imagePath))
            return imagePath;

        var directory = Path.Combine(Path.GetTempPath(), "AutoTreasureHunt");
        Directory.CreateDirectory(directory);
        imagePath = Path.Combine(directory, "dny.jpg");
        if (!File.Exists(imagePath) || new FileInfo(imagePath).Length == 0)
        {
            var data = Convert.FromBase64String(string.Concat(Base64Chunks));
            File.WriteAllBytes(imagePath, data);
        }

        return imagePath;
    }
}
